      // @knowledge 98e0fbdd-a9ac-44d3-9e4f-d3adadeffa69@14ec74ace776a6a7
      parentPatchId = IdConv.toProto(d.parentPatchId),
      // @knowledge 1c36e604-45c4-4106-848c-df7155df7e04@59417bbaa3e0d447
      patchHash = d.patchHash,
      // @knowledge 614d234c-f684-4026-8b0b-c8e6c9e3611a@014c7eee9fb65151
      concepts = d.concepts.map(ConceptDeltaConv.toProto),
      // @knowledge 74daf424-0b46-4237-b049-54b95d5e5c15@aa591a2a8bb32f42
      relations = d.relations.map(RelationDeltaConv.toProto),
      // @knowledge 758e13e5-9afd-43fb-971a-0a9b6618ee2e@0b2fdf87046708f0
      createdAt = InstantConv.toProto(d.createdAt),
      // @knowledge af5f28e3-0a16-44e0-828a-e848ac430fb7@ed3c361045a50ab1
      mergedAt = InstantConv.toProto(d.mergedAt)
    )

    override def fromProto(p: KnowledgePatchStatePO): KnowledgePatchState = KnowledgePatchState(
      // @knowledge 1baaf26b-15c4-4139-a9b0-f6a966914ead@3586dc64a04e4278
      patchId = IdConv.fromProto(p.patchId),
      // @knowledge 7b09d2d5-13e9-4162-a348-4d0f4cd14f8c@0997b8fd0252e423
      tenantId = IdConv.fromProto(p.tenantId),
      // @knowledge ffa73c70-4aa1-4dbb-a30c-93f443a1d843@332311f41e299e39
      status = p.status,
      // @knowledge 0cfe2128-98b5-47a6-a45e-a45389d02ebb@40083e726659d319
      sessionIds = p.sessionIds.map(IdConv.fromProto).toList,
      // @knowledge e26fb65c-26e2-4dc7-801d-71719ace9b36@80b40d4b9d64ca7d
      catalogId = IdConv.fromProto(p.catalogId),
      // @knowledge 37635613-ba37-4756-8848-34de0d2ec0fd@15596e973d9761b0
      contextId = IdConv.fromProto(p.contextId),
      // @knowledge e8400121-f50d-444c-bae5-58c3c1e0c0f8@d4bf33e142836c19
      createdBy = p.createdBy,
      // @knowledge 98e0fbdd-a9ac-44d3-9e4f-d3adadeffa69@14ec74ace776a6a7
      parentPatchId = IdConv.fromProto(p.parentPatchId),
      // @knowledge 1c36e604-45c4-4106-848c-df7155df7e04@59417bbaa3e0d447
      patchHash = p.patchHash,
      // @knowledge 614d234c-f684-4026-8b0b-c8e6c9e3611a@014c7eee9fb65151
      concepts = p.concepts.map(ConceptDeltaConv.fromProto).toList,
      // @knowledge 74daf424-0b46-4237-b049-54b95d5e5c15@aa591a2a8bb32f42
      relations = p.relations.map(RelationDeltaConv.fromProto).toList,
      // @knowledge 758e13e5-9afd-43fb-971a-0a9b6618ee2e@0b2fdf87046708f0
      createdAt = InstantConv.fromProto(p.createdAt),
      // @knowledge af5f28e3-0a16-44e0-828a-e848ac430fb7@ed3c361045a50ab1
      mergedAt = InstantConv.fromProto(p.mergedAt)
    )
  }


  object ListConv {
    def toProto[D, P](domain: List[D])(implicit c: ProtoConverter[D, P]): Seq[P] = domain.map(c.toProto)
    def fromProto[D, P](proto: Seq[P])(implicit c: ProtoConverter[D, P]): List[D] = proto.map(c.fromProto).toList
  }

  object InstantConv {
    def toProto(domain: java.time.Instant): Long = Option(domain).fold(0L)(_.toEpochMilli)
    def fromProto(proto: Long): java.time.Instant = java.time.Instant.ofEpochMilli(proto)
  }

}

/** S2-82-B3（2026-09-11）：self-companion——trait 嵌套 Conv object 的静态寻址口。
  * Scala trait 无 term（TraitName.NestedObject 编译红「no companion object」）——
  * 投影 handler/读端经 KnowledgePatchProtoConverters.XxxConv.fromProto 静态调用需要本伴生；
  * EventAdapter/SnapshotAdapter 等 mixin 消费方不受影响（trait 本体原样）。 */
object KnowledgePatchProtoConverters extends KnowledgePatchProtoConverters
